<?php $disabled = !empty($read_only) ? 'disabled' : ''; $selected = array_fill_keys((array) ($form['permissions'] ?? array()), true); $grouped = array(); foreach ((array) $permissions as $permission) { $grouped[$permission['module']][] = $permission; } $action = !empty($form['id']) ? admin_url('/roles/edit/' . (int) $form['id']) : admin_url('/roles/new'); ?>
<header class="admin-page-head compact-head"><div><a class="admin-back-link" href="<?= e(admin_url('/roles')) ?>">&lt;- Back to roles</a><p class="admin-eyebrow">Team / access</p><h1><?= !empty($form['id']) ? 'Edit role' : 'New role' ?></h1><p class="admin-lede">Give this role a clear purpose and a deliberate permission set.</p></div></header>
<?php if (!empty($errors)): ?><div class="admin-alert error" id="role-form-errors" role="alert"><ul><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="admin-editor-form" method="post" action="<?= e($action) ?>"<?= !empty($errors) ? ' aria-describedby="role-form-errors"' : '' ?>><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($form['id'] ?? 0) ?>"><div class="editor-layout"><main class="editor-main"><section class="admin-panel editor-panel"><div class="form-grid"><label><span>Title <b>*</b></span><input name="title" value="<?= e($form['title'] ?? '') ?>" required <?= $disabled ?>></label><label><span>Slug <b>*</b></span><input name="slug" value="<?= e($form['slug'] ?? '') ?>" pattern="[a-z0-9-]+" required <?= $disabled ?>></label><label class="span-2"><span>Description</span><textarea name="description" rows="4" <?= $disabled ?>><?= e($form['description'] ?? '') ?></textarea></label><label class="toggle-field"><span>Active</span><input type="checkbox" name="is_active" value="1" <?= !isset($form['is_active']) || !empty($form['is_active']) ? 'checked' : '' ?> <?= $disabled ?>><strong>Available for assignment</strong></label></div></section><section class="admin-panel editor-panel"><div class="panel-heading"><div><p class="admin-eyebrow">Permission matrix</p><h2>What this role can do</h2></div></div><p class="form-note" id="role-permissions-help">Choose only the access this role needs. System roles are protected.</p><div class="permission-groups" aria-describedby="role-permissions-help"><?php foreach ($grouped as $module => $items): ?><fieldset class="permission-group"><legend><?= e(ucwords(str_replace(array('_', '-'), ' ', $module))) ?></legend><?php foreach ($items as $permission): ?><label class="permission-item"><input type="checkbox" name="permissions[]" value="<?= e($permission['code']) ?>" <?= isset($selected[$permission['code']]) ? 'checked' : '' ?> <?= $disabled ?>><span><strong><?= e($permission['title']) ?></strong><small><?= e($permission['code']) ?></small></span></label><?php endforeach; ?></fieldset><?php endforeach; ?></div></section></main></div><?php if (empty($read_only)): ?><div class="editor-submit"><a class="admin-cancel-link" href="<?= e(admin_url('/roles')) ?>">Cancel</a><button class="admin-primary-button" type="submit">Save role <span aria-hidden="true">-&gt;</span></button></div><?php endif; ?></form>
